'use strict';
const $=id=>document.getElementById(id),{dateKey,parseDate,clone,migrate,combinations}=Corda;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let raw,state,storageReady=true;
try{raw=localStorage.getItem('corda-state');const parsed=JSON.parse(raw||'{}');state=migrate(parsed,plan);if(raw&&parsed?.version!==3)localStorage.setItem('corda-state-before-v3',raw);}catch(error){state=migrate({},plan);storageReady=false;$('storageWarning').hidden=false;$('storageWarning').textContent='Não foi possível ler ou preservar os dados existentes. Nada será sobrescrito. Exporte ou verifique o armazenamento antes de continuar.';}
state.kit=state.kit||clone(defaultKit);state.days=state.days||{};
enrichPlan();
let selectedDate=dateKey(new Date()),monthDate=parseDate(selectedDate),dialogIndex=null,registration=null;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,3500)}
function save(){if(!storageReady)return false;try{localStorage.setItem('corda-state',JSON.stringify(state));return true}catch(error){$('storageWarning').hidden=false;$('storageWarning').textContent='Armazenamento indisponível ou cheio. As últimas mudanças estão só nesta tela: exporte o histórico antes de fechar.';return false}}
if(storageReady)save();
const future=()=>selectedDate>dateKey(new Date());
function planFor(d,date){return d?.mode==='rest'?restPlan:d?.mode==='light'?lightPlan:d?.plan||plan[parseDate(date).getDay()]}
function currentPlan(){return planFor(state.days[selectedDate],selectedDate)}
function training(d){if(!d)return null;if(!d.mode||d.mode==='normal')return d;d.sessions=d.sessions||{};return d.sessions[d.mode]||(d.sessions[d.mode]={done:{},loads:{}})}
function entry(){if(future()){toast('Esta data ainda não chegou.');return null}if(!state.days[selectedDate])state.days[selectedDate]={plan:clone(plan[parseDate(selectedDate).getDay()]),done:{},notes:'',loads:{},music:{},skills:{}};const d=state.days[selectedDate];for(const key of ['done','loads','music','skills'])d[key]=d[key]||{};return d}
function show(screen){document.querySelectorAll('.screen').forEach(el=>el.classList.toggle('active',el.id===screen));document.querySelectorAll('.tabs button').forEach(el=>el.classList.toggle('active',el.dataset.target===screen));if(screen==='history')renderCalendar();if(screen==='week')renderWeek();if(screen==='music')renderMusic();window.scrollTo(0,0)}
function openDate(date){selectedDate=date;renderDay();show('today')}
function longDate(date){return new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',year:'numeric'}).format(parseDate(date))}
function renderDay(){const p=currentPlan(),d=state.days[selectedDate],session=training(d);$('dayMode').value=d?.mode||'normal';$('dayMode').disabled=future()||!!d?.unwell;$('unwell').checked=!!d?.unwell;$('unwell').disabled=future();$('warmup').hidden=['rest','light'].includes(d?.mode);$('technicalBlock').hidden=['rest','light'].includes(d?.mode);$('date').textContent=new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'short'}).format(parseDate(selectedDate))+' ▦';$('dayLabel').textContent=new Intl.DateTimeFormat('pt-BR',{weekday:'long'}).format(parseDate(selectedDate))+' · '+longDate(selectedDate);$('title').textContent=p.title;$('focus').textContent=p.focus;$('badges').innerHTML=p.badges.map(b=>`<span class="pill">${esc(b)}</span>`).join('');$('sessionHeading').textContent=selectedDate===dateKey(new Date())?'Hoje':'Treino da data';$('historyNotice').hidden=!!d&&!d.migrated;$('historyNotice').textContent=d?.migrated?'Marcações importadas da versão anterior. O plano foi reconstruído a partir daquela versão.':future()?'Prévia do plano. Os registros ficam disponíveis quando a data chegar.':'Ainda sem registro nesta data. O plano exibido é uma referência; nenhuma conclusão foi presumida.';
 $('exerciseList').innerHTML=p.items.map((item,i)=>{const info=infoFor(item[0]);return `<article class="exercise-row"><input class="check" type="checkbox" aria-label="Concluir ${esc(item[0])}" data-index="${i}" ${session?.done[i]?'checked':''} ${future()?'disabled':''}><button class="exercise-open" data-index="${i}" aria-label="Ver execução e carga: ${esc(item[0])}"><img src="illustrations/${info.art}.svg" alt="" width="64" height="64"><span><h3>${esc(item[0])}</h3><span class="dose">${esc(item[2])}</span><p>${esc(item[1])}</p><small>Ver execução${info.handles?' e anilhas':''} →</small></span></button></article>`}).join('');
 $('exerciseList').querySelectorAll('.check').forEach(input=>input.onchange=()=>{const d=entry();if(d){training(d).done[input.dataset.index]=input.checked;save();renderProgress()}});
 $('exerciseList').querySelectorAll('.exercise-open').forEach(button=>button.onclick=()=>openExercise(Number(button.dataset.index)));
 $('coachNote').innerHTML='<strong>Nota de treino</strong><p>'+esc(p.note)+'</p>';$('dailyNotes').value=d?.notes||'';$('dailyNotes').disabled=future();renderProgress();renderSkills();
}
function renderProgress(){const d=state.days[selectedDate],session=training(d),p=currentPlan(),done=p.items.filter((_,i)=>session?.done[i]).length;$('progress').textContent=p.items.length?`${done} de ${p.items.length} concluídos`:'Descanso registrado'}
function renderCalendar(){const y=monthDate.getFullYear(),m=monthDate.getMonth();$('monthTitle').textContent=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(monthDate);const first=new Date(y,m,1,12),count=new Date(y,m+1,0,12).getDate();let html=['D','S','T','Q','Q','S','S'].map(s=>`<span aria-hidden="true">${s}</span>`).join('')+'<span></span>'.repeat(first.getDay());let logged=0,finished=0;for(let day=1;day<=count;day++){const key=dateKey(new Date(y,m,day,12)),d=state.days[key],done=d?planFor(d,key).items.filter((_,i)=>training(d).done?.[i]).length:0;if(d)logged++;finished+=done;html+=`<button data-date="${key}" class="${key===selectedDate?'active':''}" ${key===dateKey(new Date())?'aria-current="date"':''} aria-label="${longDate(key)}${d?`, ${done} exercícios concluídos`:', sem registro'}">${day}<small>${d?'● '+done+'/'+planFor(d,key).items.length+(d.mode==='light'?' L':d.mode==='rest'?' R':''):'—'}</small></button>`}$('calendar').innerHTML=html;$('calendar').querySelectorAll('button').forEach(b=>b.onclick=()=>openDate(b.dataset.date));$('monthStats').textContent=`${logged} dias com registro · ${finished} exercícios marcados neste mês. Notas e musicalidade também contam como registro.`}
function renderSkills(){const d=state.days[selectedDate];$('skillList').innerHTML=technicalSkills.map(([id,name,hint])=>{const skill=d?.skills?.[id]||{};return `<details class="skill"><summary>${esc(name)}${skill.status?' · '+esc(skill.status):''}</summary><p class="muted">${esc(hint)}</p><div class="skill-grid"><label>Prática<select data-skill="${id}" data-field="status" ${future()?'disabled':''}>${['','Educativo','Com assistência','Pratiquei com controle','Preciso de correção'].map(v=>`<option value="${v}" ${skill.status===v?'selected':''}>${v||'Não registrei'}</option>`).join('')}</select></label><label>Lado<select data-skill="${id}" data-field="side" ${future()?'disabled':''}>${['','Direito','Esquerdo','Ambos','Não se aplica'].map(v=>`<option value="${v}" ${skill.side===v?'selected':''}>${v||'Escolher'}</option>`).join('')}</select></label></div><label>Fluidez e correção<textarea data-skill="${id}" data-field="note" ${future()?'disabled':''}>${esc(skill.note||'')}</textarea></label></details>`}).join('');$('skillList').querySelectorAll('select,textarea').forEach(input=>input.addEventListener(input.tagName==='SELECT'?'change':'input',()=>{const d=entry();if(d){const id=input.dataset.skill;d.skills[id]=d.skills[id]||{};d.skills[id][input.dataset.field]=input.value;save()}}))}
function formatKg(n){return new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n)}
function assembly(option){const parts=option.counts.map((count,i)=>count?`${count} × ${formatKg([1.25,1.5,2][i])} kg`:'').filter(Boolean);return parts.length?parts.join(' + '):'sem anilhas'}
function loadLabel(option){const bar=state.kit.barWeight;return `${formatKg(option.plates)} kg de anilhas por halter${bar===null||bar===''?' + barra (peso não informado)':` = ${formatKg(option.plates+Number(bar))} kg por halter`}`}
function openExercise(i,previewPlan=null){dialogIndex=i;const item=(previewPlan||currentPlan()).items[i],info=infoFor(item[0]),d=previewPlan?null:training(state.days[selectedDate]);$('exerciseTitle').textContent=item[0];let html=`<img src="illustrations/${info.art}.svg" alt="${esc(artDescriptions[info.art])}"><p class="detail-caption">Esquema simplificado de apoio; confira a execução com seu professor.</p><ol>${info.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p><strong>${esc(item[2])}</strong> · ${esc(item[1])}</p>`;
 if(info.handles){const options=combinations(state.kit,info.handles),record=d?.loads?.[i];const suggested=options.find(o=>o.plates>=info.start)||options[0];const selected=record?.plates??suggested.plates;html+=`<div class="note"><strong>Primeiro teste leve: ${formatKg(suggested.plates)} kg de anilhas por halter + barra</strong><p>${info.handles===2?'Monte dois halteres iguais.':'Use um halter; para exercício unilateral, alterne os lados.'} Em <b>cada lado de cada halter</b>: ${assembly(suggested)}.</p><p>É um ponto de partida para experimentar, não uma carga personalizada inferida da foto. Faça algumas repetições controladas; se pesar, use a barra vazia ou uma variação mais fácil. Se ficar leve, ajuste aos poucos mantendo cerca de 2 repetições boas na reserva.</p></div><div class="field"><label for="loadChoice">${previewPlan?'Consultar montagem':'Carga usada nesta data'}</label><select id="loadChoice" ${!previewPlan&&future()?'disabled':''}>${options.map((o,j)=>`<option value="${j}" ${o.plates===selected?'selected':''}>${esc(loadLabel(o))}</option>`).join('')}</select><p id="assemblyText"></p><button id="saveLoad" class="primary" ${previewPlan?'hidden':''} ${future()?'disabled':''}>Registrar carga do dia</button><p id="recordedLoad">${previewPlan?'Consulta do planejamento. Abra o registro da data para salvar a carga usada.':record?'Registrado: '+esc(record.label):'Ainda não registrada; a sugestão não é salva como treino realizado.'}</p></div>`;
 $('exerciseDetail').innerHTML=html;const update=()=>{const o=options[Number($('loadChoice').value)];$('assemblyText').textContent=`Cada lado: ${assembly(o)}. Total utilizado: ${formatKg(o.plates*info.handles)} kg de anilhas em ${info.handles} halter(es). Monte os lados simétricos e confira as travas.`};$('loadChoice').onchange=update;update();$('saveLoad').onclick=()=>{const original=entry();if(!original)return;const day=training(original);const option=options[Number($('loadChoice').value)];day.loads[i]={...option,barWeight:state.kit.barWeight,label:loadLabel(option),assembly:assembly(option)};if(save()){toast('Carga registrada nesta data');$('recordedLoad').textContent='Registrado: '+day.loads[i].label}};
 }else{$('exerciseDetail').innerHTML=html+'<div class="note"><strong>Sem carga externa inicial</strong><p>Use o peso do corpo ou a variação já dominada. Registre adaptações nas observações do dia.</p></div>'}
 if(!$('exerciseDialog').open)$('exerciseDialog').showModal();
}
function renderMusic(){$('musicDate').textContent='Registro de '+longDate(selectedDate);const d=state.days[selectedDate];$('musicList').innerHTML=musicPatterns.map(p=>`<article class="music-card"><h3>${p.name}</h3><div class="symbol-line" aria-label="${esc(p.pattern.replaceAll('X','chiado ').replaceAll('○','solta ').replaceAll('●','presa '))}">${p.pattern}</div><p>${p.hint}</p><a href="${p.url}" target="_blank" rel="noopener">Ouvir / ver a referência ↗</a><label><input class="check" type="checkbox" data-music="${p.id}" ${d?.music?.[p.id]?'checked':''} ${future()?'disabled':''}> Pratiquei nesta data</label></article>`).join('');$('musicList').querySelectorAll('input').forEach(input=>input.onchange=()=>{const d=entry();if(d){d.music[input.dataset.music]=input.checked;save()}})}
$('dayMode').onchange=()=>{const d=entry();if(d){d.mode=$('dayMode').value;save();renderDay()}};
$('unwell').onchange=()=>{const d=entry();if(d){d.unwell=$('unwell').checked;if(d.unwell)d.mode='rest';save();renderDay()}};
$('dailyNotes').oninput=()=>{const d=entry();if(d){d.notes=$('dailyNotes').value;save()}};
$('date').onclick=()=>{monthDate=parseDate(selectedDate);show('history')};$('prevMonth').onclick=()=>{monthDate=new Date(monthDate.getFullYear(),monthDate.getMonth()-1,1,12);renderCalendar()};$('nextMonth').onclick=()=>{monthDate=new Date(monthDate.getFullYear(),monthDate.getMonth()+1,1,12);renderCalendar()};$('calendarToday').onclick=()=>openDate(dateKey(new Date()));$('dayMusic').onclick=()=>show('music');$('closeExercise').onclick=()=>$('exerciseDialog').close();
for(const button of document.querySelectorAll('.tabs button'))button.onclick=()=>{if(button.dataset.target==='today')openDate(dateKey(new Date()));else show(button.dataset.target)};
for(const id of ['loads','repertoire']){$(id).value=state[id]||'';$(id).oninput=()=>{state[id]=$(id).value;save()}}
$('legacyNotes').textContent=state.legacyNotes||'Nenhuma anotação anterior encontrada.';$('barWeight').value=state.kit.barWeight??'';$('barWeight').oninput=()=>{if(!$('barWeight').checkValidity())return;state.kit.barWeight=$('barWeight').value===''?null:Number($('barWeight').value);save()};
$('exportData').onclick=()=>{const blob=new Blob([JSON.stringify({app:'meu-treino-de-corda',version:3,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='treino-corda-'+dateKey(new Date())+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup preparado para download')};
function validBackup(data){if(data?.app!=='meu-treino-de-corda'||data.version!==3||data.state?.version!==3||!data.state.days||Array.isArray(data.state.days))return false;for(const [date,d] of Object.entries(data.state.days)){if(!Corda.validDate(date)||!d||!Array.isArray(d.plan?.items)||d.plan.items.length>50||!Array.isArray(d.plan.badges)||!d.plan.items.every(i=>Array.isArray(i)&&i.length===3&&i.every(v=>typeof v==='string'))||typeof d.notes!=='string')return false}const k=data.state.kit;if(k&&(!k.plates||![1.25,1.5,2].every(w=>Number.isInteger(k.plates[w])&&k.plates[w]>=0&&k.plates[w]<=20)||(k.barWeight!==null&&(!Number.isFinite(k.barWeight)||k.barWeight<0||k.barWeight>20))))return false;return true}
$('importData').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Arquivo muito grande.');const data=JSON.parse(await file.text());if(!validBackup(data))throw Error('Backup inválido ou incompatível.');if(!confirm('Substituir o histórico deste aparelho pelo backup escolhido? Exporte o atual primeiro se quiser guardá-lo.'))return;localStorage.setItem('corda-state-before-import',JSON.stringify(state));localStorage.setItem('corda-state',JSON.stringify(data.state));location.reload()}catch(error){toast(error.message)}finally{event.target.value=''}};
function offerUpdate(){if(registration?.waiting)$('updateBanner').hidden=false}
if('serviceWorker' in navigator){navigator.serviceWorker.register('sw.js').then(reg=>{registration=reg;offerUpdate();reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'){offerUpdate();$('updateStatus').textContent=reg.waiting?'Nova versão pronta no aviso acima.':'Arquivos disponíveis offline.'}})});reg.update().catch(()=>{});}).catch(()=>$('updateStatus').textContent='Não foi possível preparar o modo offline. Tente novamente com internet.');let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloading)return;reloading=true;location.reload()})}
$('applyUpdate').onclick=()=>{if(save())registration?.waiting?.postMessage({type:'SKIP_WAITING'})};$('checkUpdate').onclick=async()=>{if(!registration){$('updateStatus').textContent='Abra com internet para preparar as atualizações.';return}try{await registration.update();offerUpdate();$('updateStatus').textContent=registration.waiting?'Nova versão pronta. Use o aviso acima.':registration.installing?'Baixando atualização…':'Nenhuma versão nova encontrada.'}catch{$('updateStatus').textContent='Sem conexão para buscar atualizações. Seu histórico continua disponível.'}};

let weeklyDate=dateKey(new Date());
function currentWeekDates(){
 const monday=new Date();monday.setHours(12,0,0,0);monday.setDate(monday.getDate()-(monday.getDay()+6)%7);
 return Array.from({length:7},(_,i)=>{const day=new Date(monday);day.setDate(day.getDate()+i);return dateKey(day)});
}
function weeklyPlan(){return $('weeklyMode').value==='light'?lightPlan:$('weeklyMode').value==='rest'?restPlan:plan[parseDate(weeklyDate).getDay()]}
function renderWeek(){
 const dates=currentWeekDates();if(!dates.includes(weeklyDate))weeklyDate=dateKey(new Date());
 $('weekRange').textContent=longDate(dates[0])+' a '+longDate(dates[6]);
 $('weekDays').innerHTML=dates.map(date=>{const d=parseDate(date);return '<button class="day '+(date===weeklyDate?'active':'')+'" data-week-date="'+date+'" aria-pressed="'+(date===weeklyDate)+'" aria-label="'+longDate(date)+'" '+(date===dateKey(new Date())?'aria-current="date"':'')+'>'+plan[d.getDay()].short+'<span>'+d.getDate()+'/'+(d.getMonth()+1)+'</span></button>'}).join('');
 $('weekDays').querySelectorAll('button').forEach(button=>button.onclick=()=>{weeklyDate=button.dataset.weekDate;renderWeek()});
 const p=weeklyPlan();$('weeklyTitle').textContent=p.title;$('weeklyFocus').textContent=p.focus;$('weeklyBadges').innerHTML=p.badges.map(b=>'<span class="pill">'+esc(b)+'</span>').join('');
 $('weeklyWarmup').innerHTML=$('warmup').innerHTML;$('weeklyWarmup').hidden=$('weeklyMode').value!=='normal';
 $('weeklyList').innerHTML=p.items.map((item,i)=>{const info=infoFor(item[0]);return '<article class="exercise-row weekly-row"><button class="exercise-open" data-week-index="'+i+'"><img src="illustrations/'+info.art+'.svg" alt="" width="64" height="64"><span><h3>'+esc(item[0])+'</h3><span class="dose">'+esc(item[2])+'</span><p>'+esc(item[1])+'</p><small>Ver execução'+(info.handles?' e anilhas':'')+' →</small></span></button></article>'}).join('');
 $('weeklyList').querySelectorAll('button').forEach(button=>button.onclick=()=>openExercise(Number(button.dataset.weekIndex),p));
 $('weeklyNote').textContent=p.note;$('openWeeklyDate').textContent='Abrir registro de '+longDate(weeklyDate);
}
$('weeklyMode').onchange=renderWeek;$('openWeeklyDate').onclick=()=>openDate(weeklyDate);

renderDay();
